/**
 * API Response Types
 *
 * Shared types for REST API responses between daemon and web-ui.
 * These types define the contract for HTTP endpoints.
 */

/**
 * Common paginated response wrapper
 * AC: @api-contract ac-4
 */
export interface PaginatedResponse<T> {
  items: T[];
  total: number;
  offset: number;
  limit: number;
}

/**
 * Standard error response
 * AC: @api-contract ac-22, ac-23, ac-24
 */
export interface ErrorResponse {
  error: string;
  message?: string;
  suggestion?: string;
  details?: Array<{ field: string; message: string }>;
  current?: string;
  valid_transitions?: string[];
}

/**
 * Task summary for list endpoints
 * AC: @api-contract ac-2
 */
export interface TaskSummary {
  _ulid: string;
  slugs: string[];
  title: string;
  type: string;
  status: string;
  priority: number;
  spec_ref?: string;
  tags: string[];
  depends_on: string[];
  automation?: string;
  created_at: string;
  started_at?: string;
  notes_count: number;
  todos_count?: number;
  automation?: string;
}

/**
 * Full task with notes and todos
 * AC: @api-contract ac-5
 * AC: @ui-task-board ac-3 — description, plan_ref, session_ref for detail modal
 */
export interface TaskDetail extends TaskSummary {
  description?: string;
  derivation?: string;
  blocked_by: string[];
  depends_on: string[];
  context: string[];
  vcs_refs: string[];
  plan_ref?: string;
  session_ref?: string;
  notes: Note[];
  todos?: Todo[];
  notes_count: number;
  todos_count?: number;
}

/**
 * Task note
 */
export interface Note {
  _ulid: string;
  created_at: string;
  author: string;
  content: string;
  supersedes?: string;
}

/**
 * Task todo
 * Matches TodoSchema: id, text, done, done_at, added_at, added_by, promoted_to
 */
export interface Todo {
  id: number;
  text: string;
  done: boolean;
  done_at?: string;
  added_at: string;
  added_by?: string;
  promoted_to?: string;
}

/**
 * Spec item summary for list endpoints
 * AC: @api-contract ac-8
 */
export interface ItemSummary {
  _ulid: string;
  slugs: string[];
  title: string;
  type: string;
  status?: string;
  tags: string[];
  parent?: string;
  created_at: string;
}

/**
 * Full spec item with ACs and traits
 * AC: @api-contract ac-10
 */
export interface ItemDetail extends ItemSummary {
  description?: string;
  acceptance_criteria: AcceptanceCriterion[];
  traits: string[];
  depends_on: string[];
  priority?: number;
}

/**
 * Acceptance criterion
 */
export interface AcceptanceCriterion {
